#!/data/data/com.termux/files/usr/bin/bash
# apply_all39.sh - العلوم الإسلامية للأولى ثانوي: الجزء 1 = 27 بطاقة + الخرائط الذهنية (زر 🗺️)
# لا يمسّ مفتاح الترخيص: يضيف ملفات جديدة ووسوم script فقط في index.html بعد نسخة احتياطية.
cd ~/zad-1am/www 2>/dev/null || cd "$(dirname "$0")/www" || { echo "لم أجد مجلد www"; exit 1; }
[ -f index.html.bak_is1 ] || cp index.html index.html.bak_is1

# --- اكتشاف مفتاح مادة العلوم الإسلامية في الأولى ثانوي (كل الشعب) من db.js ---
CH=$(tr -d '\n' < db.js | sed 's/"AS1": *{"name"/\n&/' | tail -1 | sed 's/"AS2": *{"name".*//')
KI=$(printf '%s' "$CH" | grep -o '"key": *"[^"]*", *"name": *"[^"]*\(الإسلامية\|الاسلامية\)[^"]*"' | sed 's/"key": *"\([^"]*\)".*/\1/' | sort -u)
if [ -z "$KI" ]; then
  printf '%s' "$CH" | head -c 4000 > ~/storage/downloads/is1_diag.txt
  echo "لم أجد مادة العلوم الإسلامية للأولى ثانوي في db.js. كتبتُ تشخيصا في التنزيلات: is1_diag.txt - أرسله لي."
  echo "لم يُغيَّر شيء."
  exit 1
fi
JI=$(printf '%s\n' $KI | sed 's/.*/"&"/' | paste -sd, | sed 's/^/[/;s/$/]/')
echo "مفاتيح العلوم الإسلامية: $JI"

cat > is1_data.js <<'ZAD_EOF'
