ة في الرخاء وزينة في الشدة", "تنعم بمجالسته وتسعد بصحبته، فأنت معه في ربح دائم"]], ["الجليس السيئ", ["كالحداد ينفخ بكيره: خسارة دائمة", "إن لم يحرقك بناره أحرقك بشرره، وصحبته هم وحزن لازم"]]], "K": "الصاحب الصالح كبائع المسك، والسيئ كنافخ الكير، فاختر من تصاحب.", "M": ["الصحبة الصالحة مطلب إسلامي", "ترغيب في مجالسة من ينتفع به", "تحذير من مجالسة من يتأذى بمجالسته"], "X": "الأصدقاء كعطور: بعضها ينشر الطيب فيك، وبعضها يترك فيك رائحة الدخان.", "EX": [["ما فوائد الصحبة الصالحة؟", "هي عدة في الرخاء وزينة في الشدة، يستفيد منها صاحبها خيرا في دينه ودنياه."], ["ما مفاسد الصحبة السيئة؟", "خسارة دائمة وهم وحزن، إن لم تحرقك بنارها أحرقتك بشررها."]], "n": 16, "s": "i", "k": "i2"}, {"m": 2, "i": "🛡️", "t": "الحديث 6: من كمال الإيمان («احفظ الله يحفظك»)", "B": [["الراوي والرواية", ["عبد الله بن عباس رضي الله عنهما، رواه الترمذي", "حديث عظيم فيه وصايا وقواعد كلية من أهم أمور الدين"]], ["المتن", ["«احفظ الله يحفظك، احفظ الله تجده تجاهك»", "«إذا سألت فاسأل الله، وإذا استعنت فاستعن بالله»", "«واعلم أن الأمة لو اجتمعت على أن ينفعوك بشيء لم ينفعوك إلا بشيء قد كتبه الله لك... رفعت الأقلام وجفت الصحف»"]], ["الشرح", ["احفظ الله: اعرف حدوده وقف عندها، يحفظك: يصونك في نفسك وأهلك ودينك", "تجاهك: تجده معك بالحفظ والتأييد والنصرة حيثما كنت", "رفعت الأقلام: قدّر كل شيء في علم الله وانتهى", "جفت الصحف: انتهاء الأمر واستقراره فلا تبديل"]]], "K": "من حفظ الله بالطاعة حفظه الله، ولا يُسأل ولا يُستعان إلا به، والنفع والضر بقدره.", "M": ["احفظ الله: التزم أوامره واجتنب نواهيه", "الله وحده يُسأل ويُستعان به", "الضر والنفع كله بقضاء الله وقدره"], "X": "كمن أودع ماله عند أمين: من حفظ عهد الله، حفظ الله له ما هو أغلى: دينه ونفسه.", "EX": [["وضّح معنى «احفظ الله تجده تجاهك».", "التزم أوامره وابتعد عن نواهيه تجد الله معك بالحفظ والتأييد والنصرة حيثما كنت."], ["ما المقصود بقوله «إذا سألت فاسأل الله»؟", "ألا تطلب العطاء ولا تستعن إلا بالله وحده، لأنه القوي القادر الذي لا يُغلب."]], "n": 17, "s": "i", "k": "i2"}, {"m": 2, "i": "🔐", "t": "من الحديث 6: القضاء والقدر والتوكل", "B": [["نصرة الله وتأييده", ["من حفظ الله كان الله معه: يعينه وينصره ويحميه ويوفقه", "النصرة مرتبطة بطاعة الأوامر واجتناب النواهي"]], ["الإيمان بالقدر", ["سكينة واطمئنان: يثق بحفظ الله ولا يبالي بما يدبره الخلق", "«وإن يمسسك الله بضر فلا كاشف له إلا هو وإن يمسسك بخير فهو على كل شيء قدير» (الأنعام 17)", "شجاعة وإقدام: لا يخاف في الله لومة لائم ويقول الحق ولو على نفسه"]], ["الفرج مع الكرب", ["قد تتوالى على الإنسان المصائب والمحن اختبارا من الله", "إن صبر واحتسب ولم يضجر فرّج الله كربه، وكان له النصر المبين"]], ["ملخص الاستثمار السلوكي", ["أحفظ الله ليحفظني", "أؤمن بأن الله هو المؤيد والنصير فلا أسأل غيره", "أستعين بالله أولا وأتوكل عليه في كل أموري"]]], "K": "الإيمان بالقضاء والقدر سكينة وشجاعة؛ ولا يجوز اليأس عند الشدة.", "M": ["كل الخير بيد الله ولا يضر الخلق إلا بما كتبه الله", "اللجوء إلى الله يكون بسؤاله والاستعانة به", "وجوب الرضا بقضاء الله وقدره"], "X": "من علم أن النتيجة مكتوبة اطمأن: يجتهد دون خوف، ويصبر دون يأس.", "EX": [["وضّح حقيقة (قدر الله) في ضوء الحديث.", "كل ما ينفع أو يضر مكتوب عند الله، ولا ينال المرء إلا ما سبق في علم الله، فلا ينفع الخلق ولا يضرون إلا بما كتبه الله."], ["ماذا يجب عليك في حال الشدة والكرب؟", "الصبر والاحتساب والرضا بقضاء الله، واللجوء إليه بالدعاء، دون جزع ولا يأس."]], "n": 18, "s": "i", "k": "i2"}, {"m": 3, "i": "🌌", "t": "الكون يشهد بوجود الله ووحدانيته", "B": [["النص المؤطر", ["يونس 5-6: «هو الذي جعل الشمس ضياء والقمر نورا وقدره منازل لتعلموا عدد السنين والحساب...»", "إن في اختلاف الليل والنهار وما خلق الله في السماوات والأرض لآيات لقوم يتقون", "ضياء: ينبثق من جسم مضيء بذاته، نورا: ينعكس عن القمر"]], ["1) وجود الخالق حقيقة ثابتة", ["الإيمان بالله حقيقة مقررة في فطرة الإنسان منذ خُلق: «ما من مولود إلا يولد على الفطرة فأبواه يهوّدانه وينصّرانه ويمجّسانه»", "كل شيء له علة توجده أو صانع يصنعه"]], ["2) العلم يوصل إلى الإيمان", ["العالم المخلص تأمله يخرّه ساجدا لقدرة الله", "«لو كان فيهما آلهة إلا الله لفسدتا» (الأنبياء 22)", "«إنما يخشى الله من عباده العلماء» (فاطر 28)"]], ["3 و 4) المنكرون والإتقان", ["الدهريون: «ما هي إلا حياتنا الدنيا»، والمعاصرون ينسبون الخلق للصدفة والطبيعة، وهو باطل عقلا", "«سنريهم آياتنا في الآفاق وفي أنفسهم حتى يتبين لهم أنه الحق» (فصلت 53)", "«صنع الله الذي أتقن كل شيء» (النمل 88)، «والسماء بنيناها بأيد وإنا لموسعون» (الذاريات 47)"]]], "K": "الكون بنظامه المتقن وبعد الأرض عن الشمس (150 مليون كلم) يشهد بوجود خالق حكيم واحد.", "M": ["أربعة أدلة: الفطرة، العلم، رد الإلحاد، الإتقان", "الإلحاد: إنكار وجود الله", "الاستثمار: لا نغفل عن الخالق ونطيعه ونشكره"], "X": "ساعة فاخرة بآلاف التروس تدل على ساعاتي، فكيف بكون لا حد له في دقته؟", "EX": [["اختلاف الليل والنهار من دلائل عظمة الله، كيف ذلك؟", "لأنه نظام دقيق ثابت لا يتغير ولا يضطرب بحساب مقدر، وراءه خالق مدبر حكيم."], ["ما الذي يدفع الملاحدة إلى إنكار وجود الله؟", "الاستكبار عن الحق وفساد الفطرة، فوقفوا عند المحسوس المادي، وقولهم بالصدفة يخالف البداهة العقلية."]], "n": 19, "s": "i", "k": "i3"}, {"m": 3, "i": "🌿", "t": "أثر الإيمان في حياة الفرد والمجتمع: أركان الإيمان", "B": [["الآية المؤطرة", ["«يا أيها الذين آمنوا اتقوا الله وقولوا قولا سديدا» (الأحزاب 70)", "اتقوا الله: اعملوا بطاعته واجتنبوا معصيته، وقولا سديدا: صادقا وصوابا"]], ["محتوى الإيمان (حديث جبريل)", ["«أن تؤمن بالله وملائكته وكتبه ورسله واليوم الآخر وتؤمن بالقدر خيره وشره» (مسلم)"]], ["أثر كل ركن", ["بالله: يشعر بأن الله يراقبه في أفعاله", "بالملائكة: يستحيي من المعصية لأن الملائكة تحصي عليه أعماله", "بالكتب: يعتز بكلام الله ويتقرب بتلاوته والعمل به", "بالرسل: يأنس بأخبارهم وسيرهم ويتخذهم أسوة", "باليوم الآخر: ينمّي حب الخير ليلقى ثوابه", "بالقدر: ترضى نفسه وتصبر"]]], "K": "للإيمان ستة أركان، ولكل ركن أثر في سلوك المؤمن.", "M": ["احفظ الأركان الستة وأثر كل منها", "الإيمان يغيّر السلوك لا الاعتقاد فقط"], "X": "الإيمان كجذر الشجرة: غير مرئي لكنه يظهر في الثمر (السلوك).", "EX": [["ما هي أركان الإيمان؟", "الإيمان بالله وملائكته وكتبه ورسله واليوم الآخر والقدر خيره وشره."], ["ما أثر الإيمان بالملائكة؟", "يجعل المؤمن يستحيي من معصية الله لعلمه أن الملائكة تحصي عليه أعماله."]], "n": 20, "s": "i", "k": "i3"}, {"m": 3, "i": "🙂", "t": "أثر الإيمان في حياة الفرد", "B": [["1) الكرامة", ["«ولقد كرمنا بني آدم وحملناهم في البر والبحر ورزقناهم من الطيبات وفضلناهم على كثير ممن خلقنا تفضيلا» (الإسراء 70)", "المؤمن يعتز بإيمانه وارتباطه بكل ما في الوجود فيحيا عزيز النفس عالي الهمة"]], ["2) السعادة", ["فقدان السعادة يعني القلق والاضطراب النفسي", "«إن الإنسان خلق هلوعا إذا مسه الشر جزوعا» (المعارج 19-22)", "السعادة: صفاء نفس واطمئنان قلب وانشراح صدر وراحة ضمير، لا تشترى بالمال"]], ["3) حب الله", ["المؤمن أدرك سر الوجود فأحب الله، وأحب القرآن والنبي ﷺ وأهل الخير"]], ["4) الأمن النفسي", ["«الذين آمنوا ولم يلبسوا إيمانهم بظلم أولئك لهم الأمن وهم مهتدون» (الأنعام 82)", "«هو الذي أنزل السكينة في قلوب المؤمنين» (الفتح 4)"]], ["5) الثبات في الشدائد", ["يقول: «لا حول ولا قوة إلا بالله»، «إنا لله وإنا إليه راجعون»، «حسبنا الله ونعم الوكيل»", "من تخلو قلوبهم من الإيمان أشد الناس جزعا وأسرعهم انهيارا (الحج 11)", "فنجد الانتحار أكثر ما يكون في البيئات ضعيفة التدين"]]], "K": "الإيمان يمنح الفرد الكرامة والسعادة وحب الله والأمن النفسي والثبات.", "M": ["خمسة آثار: الكرامة، السعادة، حب الله، الأمن، الثبات", "السعادة حقيقية معنوية لا تُشترى"], "X": "الإيمان كمظلة: لا يمنع المطر (الشدائد) لكنه يحميك من البلل (الانهيار).", "EX": [["عدّد آثار الإيمان على المسلم، واشرح واحدا منها في سطرين.", "الكرامة، السعادة، حب الله، الأمن النفسي، الثبات في الشدائد. مثال الثبات: المؤمن يقول «حسبنا الله ونعم الوكيل» عند النكبات فيطمئن قلبه ويصبر."], ["ما الفرق بين السعادة الحقيقية والمال؟", "السعادة شيء معنوي يشعر به المؤمن بين جوانحه من صفاء ورضا، ولا يُشترى ولا تحويه الخزائن."]], "n": 21, "s": "i", "k": "i3"}, {"m": 3, "i": "🏛️", "t": "أثر الإيمان في حياة المجتمع", "B": [["مجتمع بلا إيمان", ["مجتمع غابة: الحياة فيه للأقوى لا للأفضل، غاياته لا تتجاوز الشهوات «والذين كفروا يتمتعون ويأكلون كما تأكل الأنعام» (محمد 12)"]], ["1) الإيمان والأخلاق", ["الدين والأخلاق متلازمان، وحدد الرسول ﷺ غاية رسالته: «إنما بعثت لأتمم مكارم الأخلاق»", "ضعف الأخلاق دليل على ضعف الإيمان: «والله لا يؤمن... الذي لا يأمن جاره بوائقه»", "«قد أفلح المؤمنون» (المؤمنون 1-11): دمج العبادة والأخلاق"]], ["2) الإيمان والإنتاج", ["المؤمن يندفع إلى العمل بإيحاء من داخله لا سوطا من الخارج", "عمارة الأرض مهمته، والجنة لأهل الجد والعمل: «وتلك الجنة التي أورثتموها بما كنتم تعملون» (الزخرف 72)"]], ["3) الإيمان والإصلاح", ["الباعث على الإصلاح هو الإيمان بالله، «ألا يعلم من خلق وهو اللطيف الخبير» (الملك 13-14)", "«فمن اتقى وأصلح فلا خوف عليهم ولا هم يحزنون» (الأعراف 35)", "لا يقوم بالإصلاح إلا من عمر قلبه بخشية الله وتقواه"]]], "K": "الإيمان يضبط أخلاق المجتمع ويدفع للعمل والإنتاج والإصلاح.", "M": ["ثلاثة آثار: الأخلاق، الإنتاج، الإصلاح", "الاستثمار: أتصف بالأخلاق الحسنة لأحقق غاية بعثة نبينا ﷺ"], "X": "المجتمع المؤمن كبستان منظم لكل غصن فيه سقاية، والمجتمع بلا إيمان غابة.", "EX": [["ما الفرق بين المؤمن والفاسق والمنافق؟", "المؤمن صدّق بقلبه وعمل بجوارحه؛ الفاسق مؤمن يعصي؛ والمنافق يظهر الإيمان ويبطن الكفر."], ["ما آثار الإيمان على المجتمع؟ مثّل.", "الأخلاق (الأمانة وكف الأذى عن الجار)، الإنتاج (السعي في عمارة الأرض)، الإصلاح (اتقاء الله والإصلاح بين الناس)."]], "n": 22, "s": "i", "k": "i3"}, {"m": 3, "i": "🙏", "t": "أدب المؤمن مع الله تعالى: الوجوب والحكمة", "B": [["تمهيد", ["الأدب: اجتماع خصال الخير في العبد، والأدب مع الله أصل كل أدب", "نوح 13-15: «ما لكم لا ترجون لله وقارا وقد خلقكم أطوارا»: لا تخافون عظمة الله وسلطانه"]], ["1) وجوب التأدب", ["ينظر المسلم إلى نعم الله التي لا تعد، فيشكره بلسانه وبجوارحه بتسخيرها في طاعته", "من سوء الأدب كفران النعم: «فاذكروني أذكركم واشكروا لي ولا تكفرون» (البقرة 152)"]], ["2) لماذا التأدب؟", ["شكر الله على نعمه والحياء منه عند الميل إلى معصيته، وصدق الإنابة والتوكل", "بقدر التمسك بالأدب تعلو الدرجة ويرتفع المقام ويصبح من أهل ولاية الله ورعايته"]], ["3) من صور تأدب الرسول ﷺ", ["«وإنك لعلى خلق عظيم» (القلم 4)", "عبد شكور: يقوم الليل حتى تتفطر قدماه: «أفلا أكون عبدا شكورا» (البخاري ومسلم)", "أشد الناس خوفا من الله: «والله إني لأخشاكم لله وأتقاكم له»", "يحب ذكر الله: «لأن أقول سبحان الله والحمد لله ولا إله إلا الله والله أكبر أحب إليّ مما طلعت عليه الشمس» (مسلم)"]]], "K": "الأدب مع الله شكر على نعمه وحياء منه، وقدوتنا فيه رسول الله ﷺ.", "M": ["الأدب مع الله أصل كل أدب", "الرسول ﷺ أشكر الناس وأخشاهم لله", "النظر في نعم الله وصفاته سبب للتأدب"], "X": "إذا أنعم عليك ملك بمنزل وعيش، لا تعصيه في داره؛ فكيف بمن خلقك وأنعم عليك؟", "EX": [["لماذا كان التأدب لازما مع الله؟", "لأن نعمه لا تحصى فيجب شكره وطاعته، وبالأدب تعلو درجة المؤمن ويصبح من أهل ولاية الله ورعايته."], ["لماذا كان الرسول ﷺ يكثر قيام الليل رغم أن الله وعده بالجنة؟", "ليكون عبدا شكورا؛ فالعبادة شكر لنعم الله، مع شدة خوفه وخشيته."]], "n": 23, "s": "i", "k": "i3"}, {"m": 3, "i": "💎", "t": "مظاهر التأدب مع الله (1-5): إخلاص، توكل، صبر، شكر، خوف", "B": [["1) الإخلاص", ["إخلاص النية لله في كل عمل فتنقلب الأعمال المباحة عبادات", "«أخلص دينك يكفك العمل القليل» (الحاكم)", "الرياء نقيض الإخلاص وتوجب اللوم والعقوبة (الماعون 4-7)"]], ["2) التوكل", ["«قل لن يصيبنا إلا ما كتب الله لنا هو مولانا وعلى الله فليتوكل المؤمنون» (التوبة 51)", "«لو أنكم توكلون على الله حق توكله لرزقكم كما يرزق الطير تغدو خماصا وتروح بطانا»", "التوكل لا يعني التخاذل: «اعقلها وتوكل»"]], ["3) الصبر", ["مثل أيوب عليه السلام: «إنا وجدناه صابرا نعم العبد إنه أواب» (ص 44)", "سورة العصر: الخسران على من لم يكن من أهل الصبر، و«واستعينوا بالصبر والصلاة» (البقرة 45)"]], ["4) الشكر", ["«كلوا من طيبات ما رزقناكم واشكروا لله» (البقرة 172)", "«ومن يشكر فإنما يشكر لنفسه ومن كفر فإن الله غني حميد» (لقمان 12)"]], ["5) الخوف", ["ينظر المسلم إلى شدة بطش ربه فيتقيه بطاعته (البروج 12-13)", "كلما قوي الإيمان قوي الخوف من الله، وكلما ضعف ضعف الخوف"]]], "K": "الإخلاص والتوكل والصبر والشكر والخوف من مظاهر التأدب مع الله.", "M": ["الأخذ بالأسباب مع التوكل", "الصبر مقرون بالصلاة", "الشكر يعود نفعه على الشاكر"], "X": "التوكل: قيّد دابتك ثم توكل؛ فالطير يخرج بحثا عن الرزق لا ينتظره في عشه.", "EX": [["ما معنى التوكل؟ وهل يعني ترك الأسباب؟", "تفويض الأمر إلى الله مع الأخذ بالأسباب، ولا يعني التخاذل والكسل: «اعقلها وتوكل»."], ["ما الرياء وما حكمه؟", "الرياء إدخال الناس في العبادة طلبا لثنائهم، نقيض الإخلاص وتوجب اللوم والعقوبة."]], "n": 24, "s": "i", "k": "i3"}, {"m": 3, "i": "🌸", "t": "مظاهر التأدب مع الله (6-9): الرجاء، الحياء، حسن الظن، القسم", "B": [["6) الرجاء", ["أن ترجو الدار الآخرة وما يقرب إليها من قول أو عمل", "الرجاء غير التمني: التمني بدون سعي، والرجاء مع العمل: «فمن كان يرجو لقاء ربه فليعمل عملا صالحا» (الكهف 110)"]], ["7) الحياء", ["«استحيوا من الله حق الحياء»: أن تحفظ الرأس وما وعى والبطن وما حوى وتذكر الموت والبلى وتترك زينة الدنيا", "المراد: يحفظ السمع والبصر واللسان إلا في طاعة الله، وأن يكون مأكله ومشربه حلالا"]], ["8) حسن الظن بالله", ["من سوء الأدب أن يسيء المرء الظن بالله فيعصيه ويخرج عن طاعته (فصلت 22-23)", "ولا يظن أنه غير مجازيه على عمله: «فلنحيينه حياة طيبة ولنجزينهم أجرهم بأحسن ما كانوا يعملون» (النحل 97)"]], ["9) القسم بالله", ["لا نُقسم إلا بالله: «من كان حالفا فليحلف بالله أو ليصمت»", "ومن حلف بالله عليه ألا يحنث في يمينه"]]], "K": "الرجاء مع العمل، والحياء من الله، وحسن الظن به، والحلف بالله وحده.", "M": ["الاستثمار: أشكر الله وأستحيي منه، أتوكل وأحسن الظن به، لا أحلف إلا بالله وفي الحق", "إذا حنثت فعليّ أن أعجّل بالكفارة"], "X": "الحياء من الله حارس داخلي: يمنعك من المعصية حتى بلا رقيب.", "EX": [["ما الفرق بين الرجاء والتمني؟", "الرجاء مع السعي والعمل، والتمني مع الكسل بلا ثمن، كمن يتمنى الجنة دون أن يعمل لها."], ["اذكر الآداب الواجبة نحو الله مع الاستشهاد.", "الإخلاص «أخلص دينك»، التوكل «وعلى الله فليتوكل المؤمنون»، الصبر «نعم العبد إنه أواب»، الشكر «واشكروا لله»، الخوف «إن بطش ربك لشديد»."]], "n": 25, "s": "i", "k": "i3"}, {"m": 3, "i": "🕋", "t": "العبادة في الإسلام: المهمة والحقيقة والمجالات", "B": [["النص المؤطر", ["«وما خلقت الجن والإنس إلا ليعبدون ما أريد منهم من رزق وما أريد أن يطعمون» (الذاريات 56-60)", "ليعبدون: لعبادتي وحدي دون من سواي، ذو القوة المتين: الشديد الذي لا يُقهر"]], ["1) مهمة الإنسان الأولى", ["خلق الله الإنسان لمهمة عظيمة هي طاعته وعبادته، وجعلها ميدان ابتلاء", "«أحسب الناس أن يتركوا أن يقولوا آمنا وهم لا يفتنون» (العنكبوت 2)", "الحكمة: أن يكون عبدا لله في الأرض ثم ينقله بالموت من دار العمل إلى دار الجزاء"]], ["2) حقيقة العبادة", ["كل ما يحبه الله ويرضاه من الأقوال والأعمال الظاهرة والباطنة", "تتضمن غاية الذل لله مع المحبة له", "من أمرين: الطاعة والخضوع، وحب الله تعالى"]], ["3) مجالات العبادة", ["تسع الحياة كلها لا الصلاة والصيام والحج فقط", "كل عمل اجتماعي نافع قُصد به وجه الله عبادة: مسح دمعة محزون، الأخذ بيد فقير، دفع الأذى عن الطريق", "حتى الحاجات الضرورية من أكل وشرب وزواج إذا صحت فيها النية"]]], "K": "العبادة غاية الخلق وهي شاملة لكل ما يحبه الله ويرضاه، وتحوّل النية المباحات إلى عبادات.", "M": ["العبادة = غاية الخضوع + غاية الحب", "العبادة لا تقتصر على الشعائر", "النية تحوّل العادة إلى عبادة"], "X": "الطالب الذي يذاكر بنية خدمة أمته يعبد الله بدراسته، وتصير كل ساعة عبادة.", "EX": [["ما الغاية التي خُلقنا من أجلها؟ وما مرتبة الدنيا بالنسبة للآخرة؟", "العبادة (طاعة الله وحده)؛ والدنيا دار امتحان وعمل، والآخرة دار الجزاء."], ["أعطِ أمثلة على تحويل العادات المباحة إلى عبادات.", "الأكل للتقوي على الطاعة، والنوم للاستعداد لقيام الفجر، والدراسة لخدمة الأمة، والزواج لإعفاف النفس، بنية صالحة."]], "n": 26, "s": "i", "k": "i3"}, {"m": 3, "i": "🕌", "t": "لماذا نعبد الله؟ والشعائر الكبرى (الصلاة)", "B": [["لماذا نعبد الله؟", ["الإنسان معقد التكوين: كتلة من طين الأرض ونفخة من روح الله", "فشاء الله أن يفرض عليه عبادات في مصلحته في الدنيا والآخرة تصله بالله وتحرره من أسر المادة", "الأصل في العبادة: امتحان لعبودية الإنسان، والله غني عن العالمين (لقمان 12)"]], ["الشعائر الكبرى", ["الصلاة والزكاة والصوم والحج، وهي مع الشهادتين أركان الإسلام الخمسة", "الأركان الأربعة الحد الأدنى: التقصير فيها من كبائر الذنوب", "التنفل يزيد القرب: «وما تقرب إلي عبدي بشيء أحب إلي مما افترضته عليه ولا يزال عبدي يتقرب إلي بالنوافل حتى أحبه»"]], ["أ) الصلاة", ["حقيقتها: عبادة تتضمن أقوالا باللسان وأفعالا بالبدن، مفتتحة بالتكبير ومختتمة بالتسليم", "شروطها: طهارة الثوب والبدن والمكان، وهي أهم أركان الإسلام العملية"]]], "K": "فُرضت العبادات لمصلحة الإنسان الروحية والمادية، وشعائر الإسلام الكبرى: الصلاة والزكاة والصوم والحج.", "M": ["أركان الإسلام: الشهادتان + الصلاة + الزكاة + الصوم + الحج", "الله غني عن عبادتنا ونحن المحتاجون", "الصلاة: تبدأ بالتكبير وتنتهي بالتسليم"], "X": "العبادات كتمارين للروح: لا يحتاجها المدرب بل المتدرب، فنفعها يعود علينا.", "EX": [["لماذا فرض الله العبادات على الإنسان؟", "لأنها في مصلحته الفردية والاجتماعية والدنيوية والأخروية: تصله بالله وتحرره من أسر المادة، والله غني عنها."], ["اذكر الشعائر الكبرى للإسلام وعرّف الصلاة.", "الصلاة والزكاة والصوم والحج؛ والصلاة عبادة قولية وفعلية مفتتحة بالتكبير ومختتمة بالتسليم، تشترط لها طهارة الثوب والبدن والمكان."]], "n": 27, "s": "i", "k": "i3"}];
