    IS1_DATA.forEach(function(c){
      var k=c.n<10?'0'+c.n:''+c.n;
      L.push({title:k+'. '+fx(c.t),content:text(c)});
    });
    var o=A[KEY]||{};
    o.name=o.name||'العلوم الإسلامية';
    o.lessons=L;
    o.maps='is1';
    A[KEY]=o;
  });
})();
ZAD_EOF
