(function(){
  if(typeof openMaps!=='function')return;
  var o=openMaps;
  window.openMaps=function(k){
    try{var d=getSubjectData(k);if(d&&d.maps==='is1'){
      openWebview('maps_is1.html','🗺️ خرائط العلوم الإسلامية - الأولى ثانوي');return}}catch(e){}
    return o(k);
  };
})();

